package com.kisanprocure.service;
import com.kisanprocure.dto.auth.AuthDtos.*; import com.kisanprocure.entity.*; import com.kisanprocure.entity.enums.Role; import com.kisanprocure.exception.ApiException; import com.kisanprocure.repository.*; import com.kisanprocure.security.JwtService; import lombok.RequiredArgsConstructor; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service;
@Service @RequiredArgsConstructor public class AuthService {
 private final UserRepository users; private final FarmerRepository farmers; private final OfficerRepository officers; private final PasswordEncoder encoder; private final JwtService jwt;
 public RegisterResponse register(RegisterRequest r){if(users.findByPhone(r.phone()).isPresent()) throw new ApiException(409,"Phone already registered"); User u=users.save(User.builder().name(r.name()).phone(r.phone()).email(r.email()).passwordHash(encoder.encode(r.password())).role(Role.FARMER).build()); farmers.save(Farmer.builder().user(u).farmerCode("FARM-"+String.format("%05d",u.getId())).village(r.village()).district(r.district()).state(r.state()).build()); return new RegisterResponse(true,"Farmer registered successfully",u.getId());}
 public LoginResponse login(LoginRequest r){User u=users.findByPhone(r.phone()).orElseThrow(()->new ApiException(401,"Invalid credentials")); if(!encoder.matches(r.password(),u.getPasswordHash())) throw new ApiException(401,"Invalid credentials"); return new LoginResponse(true,jwt.generateToken(u.getId(),u.getPhone(),u.getRole().name()),new UserSummary(u.getId(),u.getName(),u.getPhone(),u.getEmail(),u.getRole().name()));}
 public MeResponse me(Long id){User u=users.findById(id).orElseThrow(()->new ApiException(404,"User not found")); Farmer f=farmers.findByUserId(id).orElse(null); Officer o=officers.findByUserId(id).orElse(null); return new MeResponse(new UserSummary(u.getId(),u.getName(),u.getPhone(),u.getEmail(),u.getRole().name()),f==null?null:new FarmerSummary(f.getId(),f.getFarmerCode(),f.getVillage(),f.getDistrict(),f.getState()),o==null?null:new OfficerSummary(o.getId(),o.getEmployeeId(),o.getCentre().getId(),o.getCentre().getName()));}
}
